"""Edit upstream mid-run: the launcher must execute its immutable run snapshot."""
import json,os,shutil,subprocess,sys,tempfile,hashlib
from pathlib import Path
from PIL import Image
script=Path(sys.argv[1]);upstream=Path(sys.argv[2]);runtime=Path(sys.argv[3]);base=Path(tempfile.mkdtemp(prefix='rcwm-snapshot-test-'));project=base/'project';(project/'scripts').mkdir(parents=True);shutil.copy2(script,project/'scripts/rcwm_world.py');vendor=project/'vendor/RecursiveCWM';shutil.copytree(upstream,vendor);(project/'upstream.json').write_text('{}');inp=project/'inputs/test';inp.mkdir(parents=True);Image.new('RGB',(64,64)).save(inp/'reference.png');(inp/'input.json').write_text(json.dumps({'sha256':hashlib.sha256((inp/'reference.png').read_bytes()).hexdigest()}));(project/'config.json').write_text(json.dumps({'scene':'snapshot_test','reference':'inputs/test/reference.png','model':'gpt-5.6-sol','reasoning':'high','max_depth':2,'max_cycles':3}))
rt=base/'runtime';subprocess.run([str(vendor/'tools/new_workspace.sh'),str(rt),str(runtime)],check=True,stdout=subprocess.DEVNULL);fake=base/'bin';fake.mkdir();wrapper=fake/'codex'
wrapper.write_text('#!/bin/bash\nif [ "$1" = exec ]; then printf "#!/bin/bash\\nexit 77\\n" > '+str(vendor/'runner/solve_recursive.sh')+'; fi\nexec '+str(vendor/'tests/fake-codex/codex')+' "$@"\n');wrapper.chmod(0o755)
env=os.environ.copy();env.update(PATH=str(fake)+':'+env['PATH'],RCWM_ROOT=str(rt),RCWM_CLEAN_CODEX_HOME='0');result=subprocess.run([sys.executable,str(project/'scripts/rcwm_world.py'),'run','--config',str(project/'config.json')],env=env,capture_output=True,text=True)
assert result.returncode==0,(result.stdout,result.stderr,(rt/'runs/snapshot_test/launch.log').read_text());run=rt/'runs/snapshot_test';status=json.loads((run/'status.json').read_text());assert status['status']=='PROGRAM_DELIVERED';assert 'exit 77' in (vendor/'runner/solve_recursive.sh').read_text();assert 'exit 77' not in (run/'runner_source/runner/solve_recursive.sh').read_text();print('immutable launcher snapshot test passed; '+str(base))
